#!/usr/bin/env bash
# Gate F serving benchmarks on ONE GPU (default GPU 1). Model: the merged SFT checkpoint. Workload: the 500 held-out
# task prompts (chat template pre-applied), 128 output tokens forced with ignore_eos, greedy. Load is generated by
# vLLM's own `vllm bench serve`. GPU memory/power/utilization is sampled every 0.5 s while each server runs.
set -euo pipefail
GPU=${GPU:-1}
cd ~/cartograph/repo
export HF_HOME=~/cartograph/hf CUDA_VISIBLE_DEVICES=$GPU
SV=~/cartograph/venvs/serving/bin; TR=~/cartograph/venvs/training/bin/python
POLICY=~/cartograph/checkpoints/align/sft_merged
R=~/cartograph/runs/gate_f; P=$R/prompts; PORT=8011
mkdir -p $R
busy() { for _ in $(seq 12); do [ -z "$(nvidia-smi --query-compute-apps=pid --format=csv,noheader)" ] && return 1; sleep 5; done; return 0; }
[ -f $P/prompts.jsonl ] || $TR -m cartograph.serving_prompts --tasks ~/cartograph/data/tasks_v1/tasks_test.jsonl --tokenizer $POLICY --out $P
if [ ! -f $R/hf_reference/metrics.json ]; then busy && { echo "GPU busy"; exit 2; }
  $TR -m cartograph.hf_reference --model $POLICY --prompts $P/prompt_token_ids.json --num-prompts 100 --out $R/hf_reference > $R/hf_reference.log 2>&1; echo "done hf_reference"; fi

start_server() {  # name, extra vllm serve args...
  local name=$1; shift; mkdir -p $R/$name
  busy && { echo "GPU busy before $name"; exit 2; }
  (while true; do echo "$(date +%s.%N),$(nvidia-smi -i $GPU --query-gpu=memory.used,power.draw,utilization.gpu --format=csv,noheader,nounits)"; sleep 0.5; done) > $R/$name/gpu_samples.csv &
  POLL=$!
  $SV/vllm serve $POLICY --served-model-name cartograph --host 127.0.0.1 --port $PORT --max-model-len 2048 \
    --gpu-memory-utilization 0.80 --seed 0 "$@" > $R/$name/server.log 2>&1 &
  SERVER=$!
  for _ in $(seq 180); do curl -sf http://127.0.0.1:$PORT/health > /dev/null && return 0; sleep 2; done
  echo "server $name failed to start"; tail -20 $R/$name/server.log; kill $SERVER $POLL; exit 1
}
stop_server() { kill $SERVER; wait $SERVER 2>/dev/null || true; kill $POLL; sleep 5; }
bench() {  # name, tag, num_prompts, concurrency, rate, [dataset args...]
  local name=$1 tag=$2 n=$3 c=$4 rate=$5; shift 5
  local data=("$@"); [ ${#data[@]} -eq 0 ] && data=(--dataset-name custom --dataset-path $P/prompts.jsonl --custom-skip-chat-template --custom-output-len 128)
  local cflag=(); [ "$c" != none ] && cflag=(--max-concurrency $c)
  curl -s http://127.0.0.1:$PORT/metrics > $R/$name/metrics_before_$tag.prom
  $SV/vllm bench serve --backend vllm --base-url http://127.0.0.1:$PORT --model cartograph --tokenizer $POLICY \
    "${data[@]}" --ignore-eos --num-prompts $n "${cflag[@]}" --request-rate $rate --temperature 0 --seed 13 \
    --percentile-metrics ttft,tpot,itl,e2el --metric-percentiles 50,95,99 \
    --save-result --result-dir $R/$name --result-filename $tag.json > $R/$name/$tag.log 2>&1 || echo "bench $name/$tag failed"
  curl -s http://127.0.0.1:$PORT/metrics > $R/$name/metrics_after_$tag.prom
  echo "done $name/$tag"
}

# 1. bf16, prefix caching on: closed-loop concurrency sweep, then open-loop Poisson arrivals.
if [ ! -f $R/bf16/done ]; then start_server bf16 --dtype bfloat16 --enable-prefix-caching
  bench bf16 warmup 50 8 inf
  for c in 1 2 4 8 16 32 64; do n=$(( c < 25 ? 100 : 4 * c )); bench bf16 c$c $n $c inf; done
  for rate in 2 4 8 16 32; do bench bf16 rate$rate 300 none $rate; done
  stop_server; touch $R/bf16/done; fi
# 2. Batch limits: max-num-seqs at a fixed offered concurrency of 32.
for s in 4 16; do if [ ! -f $R/bf16_maxseqs$s/done ]; then start_server bf16_maxseqs$s --dtype bfloat16 --enable-prefix-caching --max-num-seqs $s
  bench bf16_maxseqs$s warmup 20 4 inf; bench bf16_maxseqs$s c32 128 32 inf; stop_server; touch $R/bf16_maxseqs$s/done; fi; done
# 3. Prefix caching: cold vs warm on a fresh server, then shared-prefix workload with caching on vs off.
for mode in on off; do name=prefix_$mode; flag=--enable-prefix-caching; [ $mode = off ] && flag=--no-enable-prefix-caching
  if [ ! -f $R/$name/done ]; then start_server $name --dtype bfloat16 $flag
    bench $name first_pass 100 1 inf; bench $name second_pass 100 1 inf
    bench $name shared_prefix_c8 200 8 inf --dataset-name prefix_repetition --prefix-repetition-prefix-len 1024 \
      --prefix-repetition-suffix-len 128 --prefix-repetition-num-prefixes 4 --prefix-repetition-output-len 64
    stop_server; touch $R/$name/done; fi; done
# 4. Weight quantization on the same merged model (no calibration): FP8 weight-only (Marlin on Ampere) and bitsandbytes 4-bit.
for q in fp8 bitsandbytes; do if [ ! -f $R/quant_$q/done ]; then start_server quant_$q --dtype bfloat16 --enable-prefix-caching --quantization $q
  bench quant_$q warmup 20 4 inf; for c in 1 8 32; do n=$(( c < 25 ? 100 : 128 )); bench quant_$q c$c $n $c inf; done
  stop_server; touch $R/quant_$q/done; fi; done
# 5. Task quality under quantization (same 500 held-out tasks as Gate D/E).
for q in fp8 bitsandbytes; do if [ ! -f $R/quality_$q/manifest.json ]; then busy && { echo "GPU busy"; exit 2; }
  $SV/python -m cartograph.eval_assistant --tasks ~/cartograph/data/tasks_v1/tasks_test.jsonl --engine vllm --model $POLICY \
    --quantization $q --evidence $R/quality_$q > $R/quality_$q.log 2>&1 || echo "quality $q failed"; echo "done quality_$q"; fi; done
echo ALL_DONE
